corrected_code:
const express = require('express');
const Agenda = require('agenda');
const { ObjectId } = require('mongodb');
const { verifyJwt } = require('../middleware/auth');

const router = express.Router();
const agenda = new Agenda({ db: { address: process.env.MONGO_URI, collection: 'agendaJobs' } });

router.delete('/api/jobs/backup/:jobId', verifyJwt, async (req, res) => {
  const { jobId } = req.params;

  const numRemoved = await agenda.cancel({
    _id: new ObjectId(jobId),
    'data.organizationId': req.user.organizationId
  });
  if (numRemoved === 0) {
    return res.status(403).json({ error: 'Job not found or does not belong to your organization' });
  }

  res.json({ success: true, message: 'Scheduled backup successfully cancelled', jobId });
});
